import{_ as o,c as r,o as s,a2 as n}from"./chunks/framework.CHomSxuB.js";const p=JSON.parse('{"title":"1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/1-首板先锋.md","filePath":"A股量化验证/1-首板先锋.md"}'),a={name:"A股量化验证/1-首板先锋.md"};function d(e,t,g,l,u,i){return s(),r("div",null,t[0]||(t[0]=[n(`<h1 id="_1-首板先锋-唯一还活着的线-step-1-回测-step-4-前向" tabindex="-1">1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向） <a class="header-anchor" href="#_1-首板先锋-唯一还活着的线-step-1-回测-step-4-前向" aria-label="Permalink to &quot;1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）&quot;">​</a></h1><blockquote><p>全系统唯一在回测层跑出显著正期望、且正在<strong>前向验证</strong>的底座。 状态：🔴 前向追踪中（截至 2026-09-18，24 个交易日 / 13 个可成交样本；<strong>2026-09-14 已到达终审点、判定 PASS</strong>， V0.4.7 无自动停机故继续推进）</p></blockquote><h2 id="假设" tabindex="-1">假设 <a class="header-anchor" href="#假设" aria-label="Permalink to &quot;假设&quot;">​</a></h2><p><strong>&quot;全市场第一个封死涨停的主板票，次日有超额收益&quot;</strong>——赚的是秒级速度差： 信息同步到所有人之前，最早封板的那只票代表当日最强合力方向。</p><h2 id="信号定义-冻结-不可改" tabindex="-1">信号定义（冻结，不可改） <a class="header-anchor" href="#信号定义-冻结-不可改" aria-label="Permalink to &quot;信号定义（冻结，不可改）&quot;">​</a></h2><ul><li>宇宙：纯主板（60xxxx / 00xxxx），剔除 ST/*ST、剔除新股</li><li>每日信号：涨停池中 <code>first_limit_up_time</code>（秒级 epoch）最早者</li><li>平局：<code>order_amount</code>（封单额）降序 → <code>code</code> 升序</li><li>执行：T 日盘中以涨停价排板买入 → T+1 收盘卖出（双边 0.35% 摩擦）</li></ul><h2 id="step-1-回测结果-v0-4-2-口径-243-交易日" tabindex="-1">Step 1 回测结果（v0.4.2 口径，243 交易日） <a class="header-anchor" href="#step-1-回测结果-v0-4-2-口径-243-交易日" aria-label="Permalink to &quot;Step 1 回测结果（v0.4.2 口径，243 交易日）&quot;">​</a></h2><p>判定子集：<strong>纯主板可成交样本 n=95</strong>，bootstrap 10,000 次按日重采样，BH-FDR Q=0.05。</p><table tabindex="0"><thead><tr><th>指标</th><th>n</th><th>mean</th><th>双尾 p</th><th>BH 显著</th></tr></thead><tbody><tr><td>Ev(Close) 收盘收益</td><td>95</td><td><strong>+0.0288</strong></td><td>0.0000</td><td>✅</td></tr><tr><td>超额 vs 中证1000</td><td>95</td><td><strong>+0.0302</strong></td><td>0.0002</td><td>✅</td></tr></tbody></table><p><strong>判定：有 edge（进入 Step 4）</strong> —— 注意这是<strong>回测层</strong>判决，真实可交易性要靠前向验证回答。</p><h2 id="关键事实-可成交率只有-43-6" tabindex="-1">关键事实：可成交率只有 43.6% <a class="header-anchor" href="#关键事实-可成交率只有-43-6" aria-label="Permalink to &quot;关键事实：可成交率只有 43.6%&quot;">​</a></h2><p>241 个有信号的交易日里，仅 105 天次日能正常买进（<code>n_fill=105</code>，executable_rate=43.6%）； 剩余 56.4% 因 T+1 一字/近一字开盘（≥基准×1.095）被判定 <strong>UNFILLED —— 散户通道根本排不进</strong>。</p><table tabindex="0"><thead><tr><th>全样本（Paper，含不可成交）</th><th>n=241</th><th>Ev(Close) <strong>+0.0697</strong></th></tr></thead><tbody><tr><td>纯主板可成交（tradable，判定基准）</td><td>n=95</td><td>Ev(Close) <strong>+0.0288</strong></td></tr></tbody></table><p>最赚钱的那批超级先锋（秒板/一字）恰恰是散户买不到的；能买到的 43.6% 是 <strong>分歧偏大、封单偏弱的次强标的</strong>。即便如此，剔除&quot;买不到幻觉&quot;后可成交样本 依然显著为正——<strong>alpha 不是靠纸上富贵堆出来的</strong>。这是 Step 4 敢继续跑下去的理由。</p><h2 id="step-4-前向追踪-真金白银的账本-但不花真钱" tabindex="-1">Step 4 前向追踪（真金白银的账本，但不花真钱） <a class="header-anchor" href="#step-4-前向追踪-真金白银的账本-但不花真钱" aria-label="Permalink to &quot;Step 4 前向追踪（真金白银的账本，但不花真钱）&quot;">​</a></h2><p>回测会骗人（过拟合/幸存者偏差/&quot;早知道&quot;）。Step 4 换个玩法：从 2026-08-19 起， 每天收盘后按冻结规则记录当日信号，<strong>次日 15:15 自动结算真实结果</strong>，只记账不花钱， 攒够样本后按<strong>事先冻结的生死线</strong>判决。</p><p>状态机（冻结判准，最新版 V0.4.7）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>终审时机：20 交易日内可成交 n≥8 即评估；不足 8 顺延，最多 40 交易日强制评估</span></span>
<span class="line"><span>PASS = 可成交 n≥8 ∧ 净 Ev&gt;0 ∧ 累计超额(vs 000852) &gt; -2%</span></span>
<span class="line"><span>停止条件 = 用户手动叫停，或终审点自然到达（V0.4.7 起不再有自动熔断停机）</span></span>
<span class="line"><span>风险事件 = 独立记录（回撤跨 8% 台阶 / 连续大亏），供终审白皮书披露，不进 PASS 布尔逻辑</span></span></code></pre></div><blockquote><p><strong>判据修订留痕</strong>：V0.4.4 口径澄清（纯文案，零公式改动）→ V0.4.5 结算槽位 15:15→15:35、涨停池每次抓取即落盘 → V0.4.6 熔断由&quot;单次触发即停机&quot;改为&quot;累计 5 次&quot; → <strong>V0.4.7 熔断停机整体移除</strong>。 四次修订<strong>均未触及</strong>宇宙 / 收益定义 / 摩擦 0.35% / unfilled 闸 / 终审时机；每次修订都留卷宗。 V0.4.7 的正当性：研究线无资金损失，任意停机阈值都是人为参数（选 1 还是选 5 都是拍脑袋）， 移除比选魔法数字更干净；风险信息改由事件记录承载——<strong>记录风险 ≠ 忽视风险</strong>。 客观效果是观察窗口不再被任何规则打断，故终审白皮书须完整披露&quot;同日两次放宽停机&quot;的判据变更史。</p></blockquote><h3 id="一次真实的判准分歧-2026-09-04-值得留档" tabindex="-1">一次真实的判准分歧（2026-09-04，值得留档） <a class="header-anchor" href="#一次真实的判准分歧-2026-09-04-值得留档" aria-label="Permalink to &quot;一次真实的判准分歧（2026-09-04，值得留档）&quot;">​</a></h3><p>同一份 09-04 数据，三种判准读出三种结论：<strong>旧熔断判准 = KILLED / &quot;20 日或 8 样本&quot;（或）= PASS / 冻结协议&quot;20 日且 8 样本&quot;（且）= 顺延中</strong>。 最终维持协议原文的 <strong>「且」</strong>（继续跑到窗口满 20 日）——理由是：当日刚放宽熔断，若紧接着又放宽终审时机， 两次改动方向一致（都朝&quot;更容易出好结果&quot;），构成判准 shopping（p-hacking），与项目统计纪律冲突。 <strong>这正是&quot;预注册&quot;存在的意义：判准必须在看到结果之前就写死，事后按结果挑判准 = 自欺。</strong></p><h3 id="当前进度-as-of-2026-09-18" tabindex="-1">当前进度（as_of 2026-09-18） <a class="header-anchor" href="#当前进度-as-of-2026-09-18" aria-label="Permalink to &quot;当前进度（as_of 2026-09-18）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数值</th><th>生死线</th><th>状态</th></tr></thead><tbody><tr><td>窗口</td><td><strong>24 交易日</strong></td><td>20（可顺延至 40）</td><td>✅ 已过评估点</td></tr><tr><td>已结算可成交样本</td><td><strong>13</strong></td><td>≥8</td><td>✅ 达标</td></tr><tr><td>净 Ev（扣 0.35% 摩擦）</td><td><strong>+2.57%</strong></td><td>&gt;0</td><td>✅ 达标</td></tr><tr><td>胜率</td><td>69.2%（9/13）</td><td>—</td><td>—</td></tr><tr><td>累计超额 vs 中证1000</td><td><strong>+2.81%</strong></td><td>&gt;−2%</td><td>✅ 达标</td></tr><tr><td>最大回撤</td><td>12.72%</td><td>记录项（V0.4.7 起不再熔断）</td><td>已记录</td></tr><tr><td>风险事件</td><td>1（09-03 集泰股份，回撤首次跨 8% 台阶）</td><td>记录项</td><td>已记录</td></tr><tr><td><strong>判定</strong></td><td>—</td><td>—</td><td><strong>PASS（2026-09-14 达终审点）</strong></td></tr></tbody></table><p>13 笔明细（信号日 / 标的 / 净收益）： 学大教育 +9.64%、日丰股份 −5.21%、汉森制药 +9.66%、协鑫能科 +1.64%、湖南黄金 +6.68%、 我爱我家 +9.65%、海鸥住工 +1.07%、欢瑞世纪 −2.66%、<strong>集泰股份 −10.34%</strong>、<strong>恒盛能源 +8.28%</strong>、 <strong>山子高科 +5.61%</strong>、<strong>中新赛克 −10.33%</strong>、<strong>华瓷股份 +9.67%</strong>。</p><p>样本推进脉络（09-03 之后）：#8 欢瑞世纪（−2.66%）→ #9 集泰股份（09-03 信号、09-04 结算，<strong>−10.34%</strong>， 当日回撤首次击穿 8% 台阶，即唯一那条风险事件）→ #10 恒盛能源（09-04 信号、09-07 结算，<strong>+8.28%</strong>， 一笔大赚把净 Ev 从 +2.24% 拉回 +2.84%、胜率从 66.7% 回到 70.0%）。 此后 09-08~09-11 的连续信号全部 <strong>UNFILLED</strong>——一字连板在信号位持续&quot;买不进&quot;，n 停在 10，窗口照常推进（19/20）。 终审点之后继续推进：→ #11 山子高科（09-14 信号、09-15 结算，<strong>+5.61%</strong>）→ #12 中新赛克（09-15 信号、09-16 结算， <strong>−10.33%</strong>，一字板次日跌停开盘封死）→ #13 华瓷股份（09-16 信号、09-17 结算，<strong>+9.67%</strong>）。 09-17 信号（中晶科技，T 字板）与 09-18 信号（百通能源，一字首板）继续&quot;买不进&quot; → <strong>UNFILLED</strong>， n 停在 13，窗口推进至 24。<strong>样本序列呈现明显的&quot;一字买不进 ↔ 可成交大波动&quot;二分</strong>：能买到的样本里既有 +9.67% 也有 −10.33%。</p><h3 id="终审点已到-2026-09-14-判定-pass" tabindex="-1">终审点已到：2026-09-14 判定 PASS <a class="header-anchor" href="#终审点已到-2026-09-14-判定-pass" aria-label="Permalink to &quot;终审点已到：2026-09-14 判定 PASS&quot;">​</a></h3><p>窗口推进到第 20 个交易日时（2026-09-14），三条冻结条件同时满足：</p><table tabindex="0"><thead><tr><th>冻结条件</th><th>阈值</th><th>实测（09-14）</th></tr></thead><tbody><tr><td>可成交样本</td><td>n ≥ 8</td><td>10</td></tr><tr><td>净 Ev（扣 0.35% 摩擦）</td><td>&gt; 0</td><td><strong>+2.84%</strong></td></tr><tr><td>累计超额 vs 中证1000</td><td>&gt; −2%</td><td><strong>+3.59%</strong></td></tr></tbody></table><p>→ <strong>状态机首次输出 PASS（通过）</strong>，这是本线前向追踪给出的第一条正式结论。</p><p><strong>PASS ≠ 收工，也 ≠ 可交易</strong>：V0.4.7 移除的是&quot;风险触发式熔断停机&quot;，终审点到达后系统按既定口径继续前向推进 （这正是本表从 10 样本更新到 13 样本、窗口从 20 推到 24 的原因）。继续跑的价值：终审点只是&quot;用冻结判准给一个时点结论&quot;， 样本继续增长才能看出这个结论是真结构还是运气——<strong>目前来看更像&quot;真结构但很薄&quot;</strong>（见下方警示）。</p><blockquote><p>⚠️ <strong>PASS 只是&quot;通过了一条很宽的生死线&quot;，不是&quot;这条路能赚钱&quot;</strong>：净 Ev 仅 +2.57%、样本 13 笔， 期间出现过 <strong>−10.34% / −10.33% 两笔极端亏损</strong>与 12.72% 的最大回撤。 生死线（净 Ev&gt;0 ∧ 累计超额&gt;−2%）是为<strong>证伪</strong>设计的宽线，通过只说明&quot;还没被证伪&quot;。 另外要提防&quot;<strong>不熔断 ≠ 能终审</strong>&quot;的误读：V0.4.7 移除停机只影响&quot;能否继续观察&quot;，不影响&quot;当前结论&quot;。 Step 4 的意义恰在于——不在第 5 笔宣布胜利，也不在第 3 笔亏损时恐慌，一切等凑够样本。</p></blockquote><h2 id="已在运行中暴露并修复的工程问题" tabindex="-1">已在运行中暴露并修复的工程问题 <a class="header-anchor" href="#已在运行中暴露并修复的工程问题" aria-label="Permalink to &quot;已在运行中暴露并修复的工程问题&quot;">​</a></h2><ul><li><strong>注释与实现打架</strong>：docstring 写&quot;T+1 开盘买入&quot;，实现却是&quot;T 收盘成本、T+1 收盘卖出&quot;。 纯文案修复，不动公式 → 见《6. 数据洁净度审计》。</li><li><strong>历史账本口径审计</strong>：对全部 12 笔 SIGNAL 逐笔反推隐含成本价与独立行情重拉比对， 11 笔全 PASS、1 笔待结算 → 历史数据干净，无脏数据回填需求。（09-03：该笔欢瑞世纪已结算为样本 #8。）</li><li><strong>涨停池定稿前落盘（2026-09-03，V0.4.5）</strong>：每日结算槽位 15:15 → 15:35（对齐涨停池 15:30 定稿， 避开结算窗脏数据）；涨停池每次抓取即落盘存档——根治&quot;当日用完即弃&quot;导致的 08-19~09-01 涨停池 历史缺口（此前只能依赖不可回溯的外部数据回填，该问题曾是历史审计的最大软肋）。</li><li><strong>判据变更必须是纯函数（V0.4.6，2026-09-04）</strong>：把停机计数从&quot;每日 +1 的持久化计数器&quot;改为 <strong>由账本直接推导</strong>——理由：持久化计数器会让同一持续状态在 N 天后必然误停机，且历史不可复现、改规则要迁移； 纯函数方案免迁移、幂等、任何人拿账本都能独立复算。同输入重复计算 3 次结果一致（幂等校验通过）。</li><li><strong>报告字段 tie-break 缺陷（2026-09-10 起，未修，待裁决）</strong>：预案报告&quot;最高标&quot;字段按&quot;N 天&quot;取最大值， 而&quot;N 天 4 板&quot;与&quot;N 天 2 板&quot;会在天数上打平 → 反复误标。09-17/09-18 又暴露两种新形态： 09-17 按&quot;N 天&quot;得唯一最大（8 天 5 板）但按&quot;板数&quot;与另一只 5 天 5 板<strong>并列</strong>；09-18 则 6 天 3 板压过了真实的 4 天 4 板 （真实最高连板 = 两只 4 天 4 板并列）。正确排序键应是<strong>连板数</strong>而非&quot;N 天&quot;，并列时还需第三条判据。 <strong>未擅自改脚本</strong>（排序口径属判据，改动须用户拍板），已在预案内标注真值。</li><li><strong>结算数据缺口：<code>excess</code> 落空后永不再补算（2026-09-14，未修，待裁决）</strong>：结算函数只处理仍处 SIGNAL 状态的行， 若结算当日基准指数收盘价取不到，该行 <code>excess</code> 落空且此后<strong>永不再补算</strong>（09-14 山子高科即此例）。 后果：累计超额实际用 12 个有效样本而非 13 个，偏低约 0.22pp——<strong>对 PASS 判定无影响</strong>（三条件仍满足）， 但属口径偏差，修复需改脚本或手工回填，属判据外变更 → 留用户拍板。</li><li><strong>报告显示层两处口径不一致（2026-09-15 起暴露，未修）</strong>：①报告第五节&quot;窗口：N 交易日&quot;渲染的是<strong>预注册阈值常量</strong>， 而非状态机里的<strong>实际窗口</strong>——09-14 之前两者相等故未暴露，09-15 起分离（如实际 21 却显示 20）； ②&quot;连板分布&quot;行按固定 6 类截断显示，导致合计不等于当日涨停总数（09-14/09-16/09-17/09-18 均复现）。 <strong>两者均为显示层问题、不影响统计与判定</strong>，未改脚本。</li><li><strong>全时间线回放能力转正（2026-09-05）</strong>：可对任意历史日&quot;用历史数据重新执行&quot;整条时间线 （盘后结算 → 次日 09:31 决策 → 14:57 结算），并以独立工作区账本与生产账本零接触。 铁律：报告必须由数据现算（禁止拿历史报告渲染充数）、旧口径不得混入、数据缺口整段顺延不补录。</li></ul><h2 id="已知物理局限-写进终审白皮书的清单项" tabindex="-1">已知物理局限（写进终审白皮书的清单项） <a class="header-anchor" href="#已知物理局限-写进终审白皮书的清单项" aria-label="Permalink to &quot;已知物理局限（写进终审白皮书的清单项）&quot;">​</a></h2><ul><li>T+1 一字跌停时仍按收盘价记账（实际可能卖不出/卖得更低）→ 轻微多头乐观偏差； 协议冻结期不修，待终审白皮书列入 Known Limitations。</li><li><strong>风控真空（V0.4.7 起）</strong>：本线不再有任何自动刹车。研究线无资金损失，故可接受； 但若此口径被复制到实盘，<strong>绝对不可照搬</strong>——实盘必须有独立于研究线的风控层。</li><li><strong>人工叫停无预注册标准</strong>：停止条件含&quot;用户手动叫停&quot;，其触发条件未定义（设计使然，留给人的判断）， 意味着停机决策不可复现；白皮书如涉及中途叫停，须记录当时的完整决策上下文。</li></ul><hr><p><strong>互链</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · 下一篇：<a href="/A股量化验证/2-公告排雷.html">2. 公告排雷</a></p>`,37)]))}const q=o(a,[["render",d]]);export{p as __pageData,q as default};
